const bySlug = new Map<string, OfficialArticle>()
for (const article of officialArticles) {
  bySlug.set(article.slug, article)
  // The crawl prefixes post files with "post__"; the app's blog routes do not.
  if (article.slug.startsWith("post__")) {
    bySlug.set(article.slug.slice("post__".length), article)
  }
}

export function findOfficialArticle(slug: string) {
  return bySlug.get(slug) ?? bySlug.get(`post__${slug}`)
}

